-- Standalone test fixture ONLY. Use a fresh disposable PostgreSQL cluster; never the application database.
create role anon; create role authenticated; create role service_role bypassrls;
create table public.choice_sections (id uuid primary key, course_id uuid, title text, opens_at timestamp with time zone, due_at timestamp with time zone, required_count integer, category_minimums jsonb, points_per_choice numeric, options jsonb, published boolean, published_at timestamp with time zone, version integer, created_at timestamp with time zone);
create table public.course_grading_settings (course_id uuid, terms jsonb, placements jsonb, revision integer, updated_by text, updated_at timestamp with time zone);
create table public.course_students (id uuid primary key, course_id uuid, student_id uuid, enrollment_state text, enrolled_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, enrolled_via text, enrolled_by uuid);
create table public.courses (id uuid primary key, google_course_id text, name text, section text, description text, room text, owner_id text, course_state text, creation_time timestamp with time zone, update_time timestamp with time zone, last_synced_at timestamp with time zone, student_count integer, created_at timestamp with time zone, updated_at timestamp with time zone, teacher_email text, join_code text, join_code_enabled boolean, join_code_expires_at timestamp with time zone, max_enrollments integer, track text, math_translation_enabled boolean, school_year text, archived_at timestamp with time zone, program text, translation_enabled boolean, lesson_experience text, present_live_layer boolean, lobby_launcher boolean, gate_checkpoints boolean, simulation_exploration_enabled boolean);
create table public.economy_point_grants (id uuid primary key, user_id uuid, user_email text, source text, reference text, points integer, note text, dedupe_key text, awarded_at timestamp with time zone, created_at timestamp with time zone, unit_id text);
create table public.interactive_assignment_submissions (id uuid primary key, assignment_id uuid, user_id uuid, state jsonb, version integer, submitted_at timestamp with time zone);
create table public.interactive_assignments (id uuid primary key, course_id uuid, slug text, target_id uuid, created_at timestamp with time zone, due_on date);
create table public.learning_targets (id uuid primary key, slug text, statement text, domain text, unit_id text, content_strand text, standard_refs text[], exclude_from_growth boolean, order_index integer, created_at timestamp with time zone, updated_at timestamp with time zone, lesson_id text, program text, reviews_capped boolean, statement_es text, xref_unit_id text);
create table public.lesson_class_windows (id uuid primary key, course_id text, lesson_id text, open_at timestamp with time zone, close_at timestamp with time zone, set_by text, updated_at timestamp with time zone, due_at timestamp with time zone);
create table public.lesson_submissions (id uuid primary key, user_id uuid, user_email text, lesson_id uuid, submitted_at timestamp with time zone, created_at timestamp with time zone, content_snapshot jsonb, response_snapshot jsonb, review_policy text);
create table public.lessons (id uuid primary key, title text, slug text, content text, description text, published boolean, created_at timestamp with time zone, updated_at timestamp with time zone, unit text, lesson_number integer, videos jsonb, estimated_time integer, objectives text[], lesson_type text, simulation_id uuid, embedded_questions jsonb, question_timing text, content_blocks jsonb, planned_days numeric(5,2), hero_image text, unit_id text, visibility_track text, transfer_core boolean);
create table public.math_mission_assignments (id uuid primary key, teacher_email text, user_id uuid, mission text, code text, title text, due_at timestamp with time zone, created_at timestamp with time zone, cancelled_at timestamp with time zone, completed_at timestamp with time zone);
create table public.math_mission_sessions (id uuid primary key, user_id uuid, user_email text, mission text, code text, mode text, seed integer, version integer, revision integer, state jsonb, status text, ranked boolean, staff boolean, challenge_day date, score integer, xp integer, assignment_id uuid, created_at timestamp with time zone, completed_at timestamp with time zone, review_note text, reviewed_at timestamp with time zone, reviewed_by text, review_rating smallint);
create table public.present_pulses (id uuid primary key, session_id uuid, kind text, anonymous boolean, salt uuid, status text, created_at timestamp with time zone, target_id uuid, prompt text, options text[], required boolean, locked boolean, revealed boolean);
create table public.present_sessions (id uuid primary key, lesson_id uuid, course_id uuid, teacher_id text, status text, current_slide integer, current_section integer, poll_block_id text, poll_locked boolean, poll_revealed boolean, blackout boolean, timer_ends_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, current_anchor text, poll_run_id uuid, projected_block_id text, projected_block_page integer, command_revision bigint, teaching_tool_state jsonb, plan_unit_id text, plan_day integer, plan_track text);
create table public.present_ticket_responses (id uuid primary key, pulse_id uuid, user_id uuid, response text, created_at timestamp with time zone);
create table public.students (id uuid primary key, email text, name text, first_name text, last_name text, profile_photo_url text, course_id text, enrollment_state text, grade_level text, student_id text, last_synced_at timestamp with time zone, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, photo_url text, alias text, last_login timestamp with time zone, cohort_year text);
create table public.textbook_assignments (id uuid primary key, course_id uuid, created_by text, title text, chapter integer, reading text, section_ids text[], instructions text, questions jsonb, due_at timestamp with time zone, status text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, origin_key text, passage text, honors_reading jsonb, opens_at timestamp with time zone);
create table public.textbook_reading_exemptions (assignment_id uuid, user_id uuid, created_by text, created_at timestamp with time zone);
create table public.textbook_submissions (id uuid primary key, assignment_id uuid, user_id uuid, answers jsonb, snapshot jsonb, submitted_at timestamp with time zone);
create table public.units (id text primary key, name text, description text, order_index integer, created_at timestamp with time zone, updated_at timestamp with time zone, allotted_days integer, program text, default_start_date date);
create table public.vocab_checks (id uuid primary key, task_id uuid, user_id uuid, items jsonb, result jsonb, created_at timestamp with time zone, completed_at timestamp with time zone, quiz_guard boolean, review_version integer, reviewed_by text, reviewed_at timestamp with time zone, requires_release boolean, review_decision jsonb);
create table public.vocab_tasks (id uuid primary key, course_id uuid, target_id uuid, title text, assigned_by text, student_ids uuid[], term_ids uuid[], words jsonb, due_on date, note text, threshold integer, min_checks integer, check_mode text, active boolean, created_at timestamp with time zone, duplicate_guard text, task_kind text, quiz_format text, syllabus_step_id text, syllabus_draft boolean);
create unique index on public.economy_point_grants(dedupe_key); grant select,insert,update on all tables in schema public to service_role;

alter table public.course_students alter id set default gen_random_uuid();
alter table public.economy_point_grants alter id set default gen_random_uuid();
alter table public.lesson_class_windows alter id set default gen_random_uuid();
